data class UserMessage(val id: Long, val text: String)

data class FeedUiState(
    val items: List<Item> = emptyList(),
    val messages: List<UserMessage> = emptyList(),
)

class FeedViewModel : ViewModel() {
    private val _state = MutableStateFlow(FeedUiState())
    val state: StateFlow<FeedUiState> = _state.asStateFlow()

    private fun showMessage(text: String) = _state.update {
        it.copy(messages = it.messages + UserMessage(System.currentTimeMillis(), text))
    }

    fun onMessageShown(id: Long) = _state.update {
        it.copy(messages = it.messages.filterNot { m -> m.id == id })
    }
}

@Composable
fun FeedScreen(viewModel: FeedViewModel, snackbarHostState: SnackbarHostState) {
    val state by viewModel.state.collectAsStateWithLifecycle()

    // Rotation cannot duplicate this: the message is removed from state only
    // once it has actually been shown and acknowledged.
    state.messages.firstOrNull()?.let { message ->
        LaunchedEffect(message.id) {
            snackbarHostState.showSnackbar(message.text)
            viewModel.onMessageShown(message.id)
        }
    }
}

// EARNS IT: combines three sources, used by several screens, real rules
class ObserveEntitlementUseCase @Inject constructor(
    private val accounts: AccountRepository,
    private val subscriptions: SubscriptionRepository,
    private val flags: FeatureFlags,
) {
    operator fun invoke(): Flow<Entitlement> = combine(
        accounts.observeCurrent(),
        subscriptions.observeActive(),
        flags.observe(Flag.PREMIUM_ROLLOUT),
    ) { account, subscription, rolloutEnabled ->
        when {
            account == null -> Entitlement.Anonymous
            subscription?.isActive == true -> Entitlement.Premium(subscription.expiresAt)
            rolloutEnabled && account.isBeta -> Entitlement.Trial
            else -> Entitlement.Free
        }
    }.distinctUntilChanged()
}

// DOESN'T: pure pass-through — delete it and call the repository
class GetUserUseCase @Inject constructor(private val repo: UserRepository) {
    suspend operator fun invoke(id: String) = repo.getUser(id)   // adds nothing
}

class FeatureFlags @Inject constructor(
    private val remote: RemoteConfigSource,
    private val local: FlagCache,
) {
    // Evaluated once per session so the UI can't flip mid-use
    private val session = mutableMapOf<Flag, Boolean>()

    suspend fun refresh() {
        runCatching { remote.fetch() }
            .onSuccess { local.save(it) }
            .onFailure { /* keep last known good — never break on a config outage */ }
    }

    fun isEnabled(flag: Flag): Boolean = session.getOrPut(flag) {
        local.get(flag)          // last known good from the server
            ?: flag.default      // compiled-in safe default
    }
}

enum class Flag(val default: Boolean, val owner: String, val removeBy: String) {
    NEW_CHECKOUT(default = false, owner = "payments", removeBy = "2026-10-01"),
    NAV3_MIGRATION(default = false, owner = "platform", removeBy = "2026-12-01"),
}

// A kill switch is checked defensively at the entry point of the risky path
fun startNewSync() {
    if (!flags.isEnabled(Flag.NEW_CHECKOUT)) return legacySync()
    newSync()
}
